*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #0f0f0f;
  --surface: #1a1a1a;
  --accent: #6c63ff;
  --text: #f0f0f0;
  --muted: #888;
  --radius: 12px;
  --font: 'Inter', sans-serif;
}

body { background: var(--bg); color: var(--text); font-family: var(--font); line-height: 1.7; }

/* NAV */
#navbar {
  position: fixed; top: 0; width: 100%; background: rgba(15,15,15,0.9);
  backdrop-filter: blur(10px); display: flex; justify-content: space-between;
  align-items: center; padding: 1rem 2rem; z-index: 100;
}
.nav-links { list-style: none; display: flex; gap: 2rem; }
.nav-links a { color: var(--text); text-decoration: none; font-weight: 600; transition: color .3s; }
.nav-links a:hover { color: var(--accent); }
.hamburger { display: none; background: none; border: none; color: var(--text); font-size: 1.5rem; cursor: pointer; }

/* HERO */
#hero {
  height: 100vh; display: flex; align-items: center; justify-content: center;
  text-align: center; padding: 2rem;
}
#hero h1 { font-size: clamp(2.5rem, 6vw, 5rem); font-weight: 800; }
.highlight { color: var(--accent); }
.tagline { color: var(--muted); margin: 1rem 0 2rem; font-size: 1.2rem; }

/* BUTTONS */
.btn {
  display: inline-block; background: var(--accent); color: #fff;
  padding: .75rem 1.75rem; border-radius: var(--radius); text-decoration: none;
  font-weight: 600; margin: .5rem; transition: opacity .3s;
}
.btn:hover { opacity: .85; }
.btn-outline { background: transparent; border: 2px solid var(--accent); color: var(--accent); }

/* SECTIONS */
section { padding: 6rem 2rem; max-width: 1100px; margin: auto; }
.section-title { font-size: 2rem; font-weight: 800; margin-bottom: 2.5rem; position: relative; }
.section-title::after {
  content: ''; display: block; width: 50px; height: 4px;
  background: var(--accent); margin-top: .5rem; border-radius: 2px;
}

/* ABOUT */
.about-grid { display: grid; grid-template-columns: 200px 1fr; gap: 3rem; align-items: center; }
.avatar { width: 200px; height: 200px; border-radius: 50%; object-fit: cover; border: 4px solid var(--accent); }

/* PROJECTS */
.projects-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.project-card {
  background: var(--surface); border-radius: var(--radius); overflow: hidden;
  transition: transform .3s; cursor: pointer;
}
.project-card:hover { transform: translateY(-6px); }
.project-card img { width: 100%; height: 180px; object-fit: cover; }
.card-body { padding: 1.25rem; }
.card-body h3 { margin-bottom: .5rem; }
.card-body p { color: var(--muted); font-size: .9rem; }
.card-links { margin-top: 1rem; display: flex; gap: 1rem; }
.card-links a { color: var(--accent); font-size: .85rem; font-weight: 600; text-decoration: none; }

/* SKILLS */
.skills-grid { display: flex; flex-wrap: wrap; gap: 1rem; }
.skill-tag {
  background: var(--surface); border: 1px solid var(--accent); color: var(--accent);
  padding: .5rem 1.25rem; border-radius: 999px; font-size: .9rem; font-weight: 600;
}

/* CONTACT */
#contact-form { display: flex; flex-direction: column; gap: 1rem; max-width: 600px; }
#contact-form input, #contact-form textarea {
  background: var(--surface); border: 1px solid #333; color: var(--text);
  padding: .85rem 1rem; border-radius: var(--radius); font-family: var(--font); font-size: 1rem;
}
#contact-form textarea { min-height: 150px; resize: vertical; }
#contact-form input:focus, #contact-form textarea:focus { outline: none; border-color: var(--accent); }

/* FOOTER */
footer { text-align: center; padding: 2rem; color: var(--muted); font-size: .85rem; }
footer a { color: var(--accent); text-decoration: none; }

/* RESPONSIVE */
@media (max-width: 700px) {
  .nav-links { display: none; flex-direction: column; position: absolute; top: 60px; right: 0;
    background: var(--surface); width: 200px; padding: 1rem; border-radius: var(--radius); }
  .nav-links.open { display: flex; }
  .hamburger { display: block; }
  .about-grid { grid-template-columns: 1fr; text-align: center; }
  .avatar { margin: auto; }
}
