// ─── PROJECT DATA ───────────────────────────────────────────
const projects = [
  {
    title: "Project One",
    description: "A full-stack web app built with React and Node.js.",
    image: "assets/images/project-1.png",
    demo: "#",
    repo: "https://github.com/yourhandle/project-one"
  },
  {
    title: "Project Two",
    description: "A mobile-first e-commerce UI with smooth animations.",
    image: "assets/images/project-2.png",
    demo: "#",
    repo: "https://github.com/yourhandle/project-two"
  },
  {
    title: "Project Three",
    description: "REST API with authentication and PostgreSQL.",
    image: "assets/images/project-3.png",
    demo: "#",
    repo: "https://github.com/yourhandle/project-three"
  }
];

// ─── RENDER PROJECT CARDS ────────────────────────────────────
const grid = document.getElementById("projects-grid");
projects.forEach(p => {
  grid.innerHTML += `
    <div class="project-card fade-in">
      <img src="${p.image}" alt="${p.title}" />
      <div class="card-body">
        <h3>${p.title}</h3>
        <p>${p.description}</p>
        <div class="card-links">
          <a href="${p.demo}" target="_blank">🔗 Live Demo</a>
          <a href="${p.repo}" target="_blank">💻 GitHub</a>
        </div>
      </div>
    </div>`;
});

// ─── SCROLL ANIMATIONS ───────────────────────────────────────
const observer = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add("visible"); });
}, { threshold: 0.15 });

document.querySelectorAll(".fade-in, section").forEach(el => {
  el.classList.add("fade-in");
  observer.observe(el);
});

// ─── NAVBAR SCROLL EFFECT ────────────────────────────────────
const navbar = document.getElementById("navbar");
window.addEventListener("scroll", () => {
  navbar.classList.toggle("scrolled", window.scrollY > 50);
});

// ─── HAMBURGER MENU ──────────────────────────────────────────
const hamburger = document.getElementById("hamburger");
const navLinks  = document.querySelector(".nav-links");
hamburger.addEventListener("click", () => navLinks.classList.toggle("open"));

// Close menu on link click
navLinks.querySelectorAll("a").forEach(a =>
  a.addEventListener("click", () => navLinks.classList.remove("open"))
);

// ─── CONTACT FORM ────────────────────────────────────────────
document.getElementById("contact-form").addEventListener("submit", e => {
  e.preventDefault();
  const data = new FormData(e.target);
  // Replace with your form service (Formspree, EmailJS, etc.)
  console.log("Form submitted:", Object.fromEntries(data));
  alert("Thanks for reaching out! I'll get back to you soon. 🚀");
  e.target.reset();
});
